DELETE FROM `user_teams`;
DELETE FROM `match_events`;
DELETE FROM `player_match_stats`;
DELETE FROM `match_state`;
DELETE FROM `match_players`;
DELETE FROM `matches`;
DELETE FROM `players`;
DELETE FROM `teams`;

